/// Returns `true` when stdin is a terminal (interactive), `false` otherwise
/// (e.g. a pipe or redirected file -- the common CI case).
///
/// Centralizes the TTY check so `add` and `init` share one predicate
/// instead of each duplicating `IsTerminal`. Thin wrapper over
/// [`std::io::IsTerminal::is_terminal`], no state -- callers inject a
/// `bool` test double rather than testing this directly, since the OS
/// determines the trait's return value, not Rust code. Non-interactive-path
/// coverage lives in `cli_tests.rs`'s `test_add_non_interactive_via_pipe`
/// (pipes stdin, asserts `callisto add` skips the TTY wizard).
pub fn is_interactive() -> bool {
    use std::io::IsTerminal as _;
    std::io::stdin().is_terminal()
}

#[cfg(test)]
mod tests {
    use super::*;

    // `add` must enter the wizard whenever stdin is
    // a TTY, regardless of stdout -- guards against a future edit growing a
    // stdout TTY check into this function. There is no pty harness in this
    // crate's dev-dependencies to fake a real stdin TTY in-process, so this
    // pins the source text instead of driving a real subprocess;
    // `cli_tests.rs`'s `test_add_non_interactive_via_pipe` covers the
    // reachable negative case (piped stdin -> NotATty).
    #[test]
    fn is_interactive_checks_stdin_only_not_stdout() {
        let needle = ["stdout", "()", ".", "is_terminal"].concat();
        let source = include_str!("tty.rs");
        assert!(
            !source.contains(&needle),
            "is_interactive must never gate on stdout's TTY-ness"
        );
        // Smoke-test the call succeeds in whatever TTY state the test runner has.
        let _: bool = is_interactive();
    }
}
use std::path::{Path, PathBuf};

use callisto_graph::infer::SeverityInference;
use callisto_graph::locate::{find_workspace_root, IgnoreWalkLocator};
use callisto_graph::resolver::ManifestWalkResolver;
use callisto_graph::Workspace;
use callisto_model::{check_git_version, CommandRunner};

use crate::cli::GlobalArgs;
use crate::error::CliError;
use crate::runner::CliCommandRunner;

/// Rejects an unsupported `git` version before any git-dependent operation runs.
fn ensure_git_supported(runner: &dyn CommandRunner, cwd: &Path) -> Result<(), CliError> {
    let output = runner.run("git", &["--version"], cwd)?;
    check_git_version(&output.stdout)?;
    Ok(())
}

pub fn load_workspace<'a>(
    global: &GlobalArgs,
    runner: &'a CliCommandRunner,
) -> Result<Workspace<'a, CliCommandRunner, ManifestWalkResolver>, CliError> {
    let root = workspace_root(global, runner)?;
    let locator = IgnoreWalkLocator::new(&root);
    Ok(Workspace::load(root, &locator, runner)?)
}

/// The workspace root above `--cwd`, after checking `git` is supported.
pub fn workspace_root(global: &GlobalArgs, runner: &dyn CommandRunner) -> Result<PathBuf, CliError> {
    let start = dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
        source,
        path: Some(global.cwd.clone()),
    })?;
    ensure_git_supported(runner, &start)?;
    Ok(find_workspace_root(&start, runner)?)
}

/// Commit inference; `release-trigger` decides per package whether it runs.
pub fn select_inference() -> impl SeverityInference {
    callisto_graph::infer::CommitInference
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use callisto_model::{CommandError, CommandOutput, CommandRunner};

    use super::*;

    #[test]
    fn load_workspace_reports_io_error_for_a_nonexistent_cwd() {
        let global = GlobalArgs {
            format: crate::cli::OutputFormat::Text,
            cwd: std::path::PathBuf::from("/nonexistent/definitely-not-a-real-path-abc123"),
            dry_run: false,
        };
        let runner = CliCommandRunner;

        match load_workspace(&global, &runner) {
            Err(CliError::Io { path, .. }) => {
                assert_eq!(path, Some(global.cwd.clone()));
            }
            Err(other) => panic!("expected CliError::Io, got a different CliError: {other:?}"),
            Ok(_) => panic!("expected an error for a nonexistent cwd, got Ok"),
        }
    }

    struct FixedVersionRunner(&'static str);

    impl CommandRunner for FixedVersionRunner {
        fn run(&self, _program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            Ok(CommandOutput {
                exit_code: Some(0),
                stdout: self.0.to_string(),
                stderr: String::new(),
            })
        }
    }

    #[test]
    fn ensure_git_supported_rejects_a_git_version_below_the_floor() {
        let runner = FixedVersionRunner("git version 1.8.5");
        match ensure_git_supported(&runner, Path::new(".")) {
            Err(CliError::Command(CommandError::IncompatibleVersion { program, .. })) => {
                assert_eq!(program, "git");
            }
            other => panic!("expected CliError::Command(IncompatibleVersion), got: {other:?}"),
        }
    }

    #[test]
    fn ensure_git_supported_accepts_a_git_version_at_the_floor() {
        let runner = FixedVersionRunner("git version 2.20.0");
        assert!(ensure_git_supported(&runner, Path::new(".")).is_ok());
    }
}
pub mod add;
pub mod completions;
pub mod compose_pr_body;
pub mod help;
pub mod init;
pub mod matrix;
pub mod pre;
pub mod release;
pub mod release_pr;
pub mod schema;
pub mod snapshot;
pub mod status;
pub mod version;

/// Reads `arg` as a JSON document: a literal `-` reads from stdin, a value
/// starting with `{` is treated as inline JSON, anything else is read as a
/// file path. Shared by every command that accepts a report/plan as either
/// a file, inline JSON, or piped stdin (`release-pr verify --decision`,
/// `--snapshot`).
pub(crate) fn read_json_arg(arg: &str) -> Result<String, crate::error::CliError> {
    if arg == "-" {
        let mut buf = String::new();
        std::io::Read::read_to_string(&mut std::io::stdin(), &mut buf)?;
        Ok(buf)
    } else if arg.trim_start().starts_with('{') {
        Ok(arg.to_string())
    } else {
        std::fs::read_to_string(arg).map_err(|source| crate::error::CliError::Io {
            source,
            path: Some(std::path::PathBuf::from(arg)),
        })
    }
}

/// Escalates workspace graph diagnostics per `strict` (via
/// `callisto_graph::commands::escalate`) and errors out naming every
/// diagnostic that is `Error` severity afterward.
///
/// Used by `snapshot`, which must abort *before* touching any
/// files/tags on an error diagnostic -- unlike `status`/`version`,
/// which fold escalated diagnostics into their report and gate on exit code
/// instead of an `Err`.
pub(crate) fn abort_on_graph_errors(
    diagnostics: &[callisto_model::Diagnostic],
    strict: bool,
) -> Result<(), crate::error::CliError> {
    let mut diags = diagnostics.to_vec();
    callisto_graph::commands::escalate(&mut diags, strict);

    let messages: Vec<String> = diags
        .iter()
        .filter(|d| d.severity == callisto_model::DiagnosticSeverity::Error)
        .map(|d| d.message.clone())
        .collect();

    if messages.is_empty() {
        Ok(())
    } else {
        Err(crate::error::CliError::StrictDiagnosticsPresent { messages })
    }
}

#[cfg(test)]
mod tests {
    use callisto_model::{Diagnostic, DiagnosticCode, DiagnosticSeverity, StrictFlag};

    use super::abort_on_graph_errors;

    fn strict_diagnostic() -> Diagnostic {
        Diagnostic {
            code: DiagnosticCode::RangeNotRoundTrippable,
            severity: DiagnosticSeverity::Warning,
            message: "graph warning a -> b".to_string(),
            package: None,
            path: None,
            escalated_by: Some(StrictFlag::Strict),
            governed_by: None,
        }
    }

    /// Without `--strict`, a `Strict`-tagged warning stays a warning, so
    /// `snapshot` must proceed rather than abort.
    #[test]
    fn without_strict_warning_diagnostics_stay_unescalated() {
        let diags = vec![strict_diagnostic()];
        assert!(abort_on_graph_errors(&diags, false).is_ok());
    }

    #[test]
    fn strict_escalates_and_aborts_naming_the_diagnostic() {
        let diags = vec![strict_diagnostic()];
        let err = abort_on_graph_errors(&diags, true).unwrap_err();
        assert!(err.to_string().contains("graph warning a -> b"));
    }
}

